describe('verifyP2PKSpendingConditions metadata', () => {
  test('non-p2pk secret', async () => {
    const proof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
