      secret: secretStr,
      witness:
        '{"signatures":["60f3c9b766770b46caac1d27e1ae6b77c8866ebaeba0b9489fe6a15a837eaa6fcd6eaa825499c72ac342983983fd3ba3a8a41f56677cc99ffd73da68b59e1383"]}',
    };
    const signedProof = signP2PKProof(proof, PRIVKEY2);
