// helpers to make valid on-curve keys, deterministically derived per label char
const _X: Record<string, string> = {};
const _xonly = (ch: string) =>
  (_X[ch] ??= bytesToHex(schnorr.getPublicKey(new Uint8Array(32).fill(ch.charCodeAt(0)))));
const _comp = (ch: string, prefix: '02' | '03' = '02') => `${prefix}${_xonly(ch)}`;

describe('normalizeP2PKOptions', () => {
  const pk = _comp('a', '02');
  const pk2 = _comp('c', '02');
  const refundPk = _comp('b', '02');
  const hashlock = 'ec4916dd28fc4c10d78e287ca5d9cc51ee1ae73cbfde08c6b37324cbfaac8bc5';

  test('throws on an unknown lock kind', () => {
    expect(() => normalizeP2PKOptions({ kind: 'FOO', data: pk } as any)).toThrow(
      /unknown lock kind: FOO/i,
    );
  });

  test('P2PK: data pubkey counts as a slot, so 11 keys fill 11 slots and 12 overflow (NUT-28)', () => {
    // NUT-28 allows up to 11 slots in [data, ...pubkeys, ...refund] (i_byte 0x00..0x0A).
    const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'a', 'b', 'c'].map((c) => _comp(c));
    const [data, ...rest] = keys; // rest has 11 distinct pubkeys
    expect(() =>
      normalizeP2PKOptions({ kind: 'P2PK', data, pubkeys: rest.slice(0, 10) }),
    ).not.toThrow(); // data + 10 pubkeys = 11 slots
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data, pubkeys: rest })).toThrow(
      /maximum allowed is 11/,
    ); // data + 11 pubkeys = 12 slots
  });

  test('HTLC: hashlock fills slot 0, so only 10 keys fit before overflowing 11 slots (NUT-28)', () => {
    // For HTLC the data slot is a hash, not a key, so signing keys max out one lower than P2PK.
    const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'a', 'b'].map((c) => _comp(c));
    expect(() =>
      normalizeP2PKOptions({ kind: 'HTLC', data: hashlock, pubkeys: keys.slice(0, 10) }),
    ).not.toThrow(); // hash + 10 pubkeys = 11 slots
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: hashlock, pubkeys: keys })).toThrow(
      /maximum allowed is 11/,
    ); // hash + 11 pubkeys = 12 slots
  });

  test('throws when P2PK data is missing or empty', () => {
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: '' })).toThrow(
      /P2PK requires a pubkey in data/i,
    );
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: undefined } as any)).toThrow(
      /P2PK requires a pubkey in data/i,
    );
  });

  test('throws when HTLC data is empty', () => {
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: '' })).toThrow(
      /HTLC requires a hashlock in data/i,
    );
  });

  test('throws when HTLC hashlock is not 64-char hex', () => {
    // A malformed hashlock yields an unspendable lock (no preimage can hash to it),
    // so reject it at construction rather than minting a dead token.
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: 'invalid_hashlock' })).toThrow(
      /HTLC hashlock must be a 64-character hex string/i,
    );
    // Right length, non-hex char.
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: 'z'.repeat(64) })).toThrow(
      /HTLC hashlock must be a 64-character hex string/i,
    );
    // Valid hex, wrong length (32 bytes expected).
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: 'ab'.repeat(20) })).toThrow(
      /HTLC hashlock must be a 64-character hex string/i,
    );
  });

  test('lowercases the HTLC hashlock so it matches createHTLCHash output', () => {
    // verifyHTLCHash compares against lowercase bytesToHex(sha256(preimage)); an
    // uppercase hashlock passes the hex check but must be canonicalised to match.
    expect(normalizeP2PKOptions({ kind: 'HTLC', data: hashlock.toUpperCase() })).toEqual({
      kind: 'HTLC',
      data: hashlock,
    });
  });

  test('splits a P2PK lock into canonical data slot + pubkeys tag', () => {
    // `data` is the NUT-10 data slot; extra keys ride the `pubkeys` tag. Empty key
    // sets are dropped from the canonical result.
    expect(
      normalizeP2PKOptions({ kind: 'P2PK', data: pk, pubkeys: [pk2], requiredSignatures: 2 }),
    ).toEqual({
      kind: 'P2PK',
      data: pk,
      pubkeys: [pk2],
      requiredSignatures: 2,
    });
  });

  test('allows a hashlock-only HTLC with no pubkeys (NUT-14)', () => {
    // An HTLC carries its lock in the hashlock, so a pubkeys list is optional.
    expect(normalizeP2PKOptions({ kind: 'HTLC', data: hashlock })).toEqual({
      kind: 'HTLC',
      data: hashlock,
    });
  });

  test('rejects an explicit n_sigs on a hashlock-only HTLC (no signers)', () => {
    // Skipping the *default* n_sigs is fine, but an explicit threshold with zero
    // signers is impossible and must fail loudly, not silently weaken the lock.
    expect(() =>
      normalizeP2PKOptions({ kind: 'HTLC', data: hashlock, requiredSignatures: 2 }),
    ).toThrow(/exceeds available pubkeys/i);
    expect(() =>
      normalizeP2PKOptions({ kind: 'HTLC', data: hashlock, requiredSignatures: 0 }),
    ).toThrow(/positive integer/i);
  });

  test('throws when a pubkeys-tag entry is an empty string', () => {
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: pk, pubkeys: [''] })).toThrow(
      /invalid pubkey/i,
    );
  });

  test('throws when refundKeys contains an empty string', () => {
    expect(() =>
      normalizeP2PKOptions({ kind: 'P2PK', data: pk, locktime: 9999, refundKeys: [refundPk, ''] }),
    ).toThrow(/invalid pubkey/i);
  });

  test('throws when requiredSignatures is not an integer', () => {
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: pk, requiredSignatures: 1.5 })).toThrow(
      /requiredSignatures \(n_sigs\) must be a positive integer/i,
    );
  });

  test('throws when requiredSignatures is less than 1', () => {
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: pk, requiredSignatures: 0 })).toThrow(
      /requiredSignatures \(n_sigs\) must be a positive integer/i,
    );
  });

  test('throws when requiredRefundSignatures is set without refundKeys', () => {
    expect(() =>
      normalizeP2PKOptions({ kind: 'P2PK', data: pk, locktime: 9999, requiredRefundSignatures: 1 }),
    ).toThrow(/requiredRefundSignatures \(n_sigs_refund\) requires refund keys/i);
  });

  test('throws when requiredRefundSignatures is not an integer', () => {
    expect(() =>
      normalizeP2PKOptions({
        kind: 'P2PK',
        data: pk,
        locktime: 9999,
        refundKeys: [refundPk],
        requiredRefundSignatures: 1.5,
      }),
    ).toThrow(/requiredRefundSignatures \(n_sigs_refund\) must be a positive integer/i);
  });

  test('throws when requiredRefundSignatures is less than 1', () => {
    expect(() =>
      normalizeP2PKOptions({
        kind: 'P2PK',
        data: pk,
        locktime: 9999,
        refundKeys: [refundPk],
        requiredRefundSignatures: 0,
      }),
    ).toThrow(/requiredRefundSignatures \(n_sigs_refund\) must be a positive integer/i);
  });

  test('throws when sigFlag is not a valid SigFlag value', () => {
    expect(() =>
      normalizeP2PKOptions({ kind: 'P2PK', data: pk, sigFlag: 'FOOBAR' as any }),
    ).toThrow(/invalid sigflag/i);
  });
});

describe('parseP2PKSecret — duplicate tag rejection', () => {
  const makePk = () => bytesToHex(getPubKeyFromPrivKey(schnorr.utils.randomSecretKey()));
  const pk1 = makePk();
  const pk2 = makePk();

  function makeSecret(tags: string[][]): string {
    return JSON.stringify(['P2PK', { nonce: bytesToHex(randomBytes(32)), data: pk1, tags }]);
  }

  test('rejects duplicate locktime tags', () => {
    const secret = makeSecret([
      ['sigflag', 'SIG_INPUTS'],
      ['locktime', '99999999999'],
      ['locktime', '1'],
      ['refund', pk2],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "locktime"/);
  });

  test('rejects duplicate sigflag tags', () => {
    const secret = makeSecret([
      ['sigflag', 'SIG_INPUTS'],
      ['sigflag', 'SIG_ALL'],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "sigflag"/);
  });

  test('rejects duplicate n_sigs tags', () => {
    const secret = makeSecret([
      ['pubkeys', pk2],
      ['n_sigs', '1'],
      ['n_sigs', '2'],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "n_sigs"/);
  });

  test('rejects duplicate n_sigs_refund tags', () => {
    const secret = makeSecret([
      ['locktime', '1'],
      ['refund', pk2],
      ['n_sigs_refund', '1'],
      ['n_sigs_refund', '2'],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "n_sigs_refund"/);
  });

  test('rejects duplicate pubkeys tags', () => {
    const secret = makeSecret([
      ['pubkeys', pk2],
      ['pubkeys', makePk()],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "pubkeys"/);
  });

  test('rejects duplicate refund tags', () => {
    const secret = makeSecret([
      ['locktime', '1'],
      ['refund', pk2],
      ['refund', makePk()],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "refund"/);
  });

  test('allows unknown/custom tags (forward compatibility)', () => {
    const secret = makeSecret([
      ['sigflag', 'SIG_INPUTS'],
      ['custom_tag', 'value1'],
      ['custom_tag', 'value2'], // duplicate custom tag is fine
    ]);
    expect(() => parseP2PKSecret(secret)).not.toThrow();
  });

  test('allows valid secret with one of each tag', () => {
    const secret = makeSecret([
      ['sigflag', 'SIG_INPUTS'],
      ['locktime', '99999999999'],
      ['pubkeys', pk2],
      ['n_sigs', '2'],
      ['refund', makePk()],
      ['n_sigs_refund', '1'],
    ]);
    expect(() => parseP2PKSecret(secret)).not.toThrow();
  });

  test('applies to HTLC secrets too', () => {
    const htlcSecret = JSON.stringify([
      'HTLC',
      {
        nonce: bytesToHex(randomBytes(32)),
        data: bytesToHex(randomBytes(32)), // hash
        tags: [
          ['locktime', '99999999999'],
          ['locktime', '1'],
          ['pubkeys', pk1],
          ['refund', pk2],
        ],
      },
    ]);
    expect(() => parseP2PKSecret(htlcSecret)).toThrow(/Duplicate P2PK tag "locktime"/);
  });
});

describe('verifyP2PKSpendingConditions — semantic validation', () => {
  const makePk = () => bytesToHex(getPubKeyFromPrivKey(schnorr.utils.randomSecretKey()));
  const pk1 = makePk();
  const pk2 = makePk();
  const pk3 = makePk();

  function makeProof(tags: string[][], data?: string): Proof {
    return {
      amount: Amount.from(1),
      id: '00000000000',
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      secret: JSON.stringify([
        'P2PK',
        { nonce: bytesToHex(randomBytes(32)), data: data ?? pk1, tags },
      ]),
    };
  }

  test('rejects n_sigs=0', () => {
    const proof = makeProof([
      ['sigflag', 'SIG_INPUTS'],
      ['n_sigs', '0'],
      ['pubkeys', pk2],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs\) must be a positive integer/,
    );
  });

  test('rejects negative n_sigs', () => {
    const proof = makeProof([
      ['n_sigs', '-1'],
      ['pubkeys', pk2],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs\) must be a positive integer/,
    );
  });

  test('rejects impossible n_sigs threshold (n_sigs > available keys)', () => {
    // 1 key in data, none in pubkeys, but n_sigs=3
    const proof = makeProof([['n_sigs', '3']]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs\) \(3\) exceeds available pubkeys \(1\)/,
    );
  });

  test('rejects n_sigs_refund=0', () => {
    const proof = makeProof([
      ['locktime', '1'],
      ['refund', pk2],
      ['n_sigs_refund', '0'],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs_refund\) must be a positive integer/,
    );
  });

  test('rejects impossible n_sigs_refund threshold', () => {
    const proof = makeProof([
      ['locktime', '1'],
      ['refund', pk2],
      ['n_sigs_refund', '3'],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs_refund\) \(3\) exceeds available refund keys \(1\)/,
    );
  });

  test('rejects refund without locktime', () => {
    const proof = makeProof([['refund', pk2]]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/refund keys require a locktime/);
  });

  test('rejects data pubkey duplicated in pubkeys tag', () => {
    const proof = makeProof([
      ['pubkeys', pk1], // same as data field
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/duplicate main pubkeys/i);
  });

  test('rejects an x-only key in the pubkeys tag as non-compliant', () => {
    const xOnly = pk1.slice(2);
    const proof = makeProof([
      ['pubkeys', xOnly], // NUT-11 requires 33-byte compressed keys
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/prepend '02'/);
  });

  test('rejects the data pubkey repeated in the pubkeys tag with flipped parity', () => {
    const proof = makeProof([
      ['pubkeys', `03${pk1.slice(2)}`], // same key, different parity byte
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/duplicate main pubkeys/i);
  });

  test('rejects duplicate refund pubkeys', () => {
    const proof = makeProof([
      ['locktime', '1'],
      ['refund', pk2, pk2],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/duplicate refund pubkeys/i);
  });

  test('returns result for well-formed unsigned proof', () => {
    const proof = makeProof([
      ['sigflag', 'SIG_INPUTS'],
      ['locktime', '99999999999'],
      ['pubkeys', pk2],
      ['n_sigs', '2'],
      ['refund', pk3],
    ]);
    const result = verifyP2PKSpendingConditions(proof);
    expect(result.success).toBe(false);
    expect(result.path).toBe('FAILED');
    expect(result.main.requiredSigners).toBe(2);
    expect(result.main.pubkeys).toHaveLength(2);
    expect(result.main.receivedSigners).toEqual([]);
  });

  test('returns success for signed proof meeting threshold', () => {
    const privKey = schnorr.utils.randomSecretKey();
    const pubKey = bytesToHex(getPubKeyFromPrivKey(privKey));
    const proof = makeProof([], pubKey);
    const signedProof = signP2PKProof(proof, bytesToHex(privKey));
    const result = verifyP2PKSpendingConditions(signedProof);
    expect(result.success).toBe(true);
    expect(result.path).toBe('MAIN');
  });

  test('duplicate locktime attack blocked at parse level before reaching semantics', () => {
    // This is the exact attack from duplicate-tag-locktime.md
    const attackerPk = makePk();
    const victimPk = makePk();
    const proof: Proof = {
      amount: Amount.from(1),
      id: '00000000000',
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      secret: JSON.stringify([
        'P2PK',
        {
          nonce: bytesToHex(randomBytes(32)),
          data: victimPk,
          tags: [
            ['sigflag', 'SIG_INPUTS'],
            ['locktime', '99999999999'], // wallet would show this
            ['locktime', '1'], // mint (CDK HashMap) would see this
            ['refund', attackerPk],
          ],
        },
      ]),
    };
    // parseP2PKSecret catches this before any signature logic
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/Duplicate P2PK tag "locktime"/);
  });
});

describe('verifyP2PKSpendingConditions signer counts', () => {
  const makePk = () => bytesToHex(getPubKeyFromPrivKey(schnorr.utils.randomSecretKey()));
  const pk1 = makePk();

  test('defaults requiredSigners to 1 when n_sigs tag is absent', () => {
    const proof: Proof = {
      amount: Amount.from(1),
      id: '00000000000',
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      secret: createP2PKsecret(pk1),
    };
    expect(verifyP2PKSpendingConditions(proof).main.requiredSigners).toBe(1);
  });

  test('uses n_sigs value when it is a valid positive integer', () => {
    const pk2 = makePk();
    const proof: Proof = {
      amount: Amount.from(1),
      id: '00000000000',
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      secret: JSON.stringify([
        'P2PK',
        {
          nonce: bytesToHex(randomBytes(32)),
          data: pk1,
          tags: [
            ['pubkeys', pk2],
            ['n_sigs', '2'],
          ],
        },
      ]),
    };
    expect(verifyP2PKSpendingConditions(proof).main.requiredSigners).toBe(2);
  });
});

describe('pubkey and hashlock format checks', () => {
  test('rejects a 66-char key with a prefix other than 02/03', () => {
    expect(() => dedupeP2PKPubkeys(['04' + 'aa'.repeat(32)])).toThrow(/Invalid pubkey/);
  });

  test('rejects an overlong key even when it starts with 02', () => {
    expect(() => dedupeP2PKPubkeys(['02' + 'aa'.repeat(33)])).toThrow(/got length 68/);
  });

  test('dedupes by full x-only portion, not just a shared suffix', () => {
    // Two distinct real keys sharing their last 2 hex chars (precomputed): the
    // regression guarded here is dedupe comparing slice(-64), not a shorter suffix.
    const k1 = '0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798';
    const k2 = '0220df196be60ba71ae617a6b144757e0e87fffb45d447d9dc0d5480a034351198';
    expect(dedupeP2PKPubkeys([k1, k2])).toStrictEqual([k1, k2]);
  });

  test('rejects x-only input and off-curve keys', () => {
    expect(() => dedupeP2PKPubkeys([_xonly('s')])).toThrow(/prepend '02'/);
    // x = field prime: well-formed but not a curve point
    const offCurve = '02fffffffffffffffffffffffffffffffffffffffffffffffffffffffefffffc2f';
    expect(() => dedupeP2PKPubkeys([offCurve])).toThrow(/secp256k1/);
  });

  test('validated-key cache clears at capacity and keeps validating', () => {
    // Overflow the 1024-entry cache with distinct valid keys, generated by point
    // addition (microseconds each) rather than scalar derivation (milliseconds).
    let p = secp256k1.Point.BASE;
    for (let i = 0; i < 1100; i++) {
      dedupeP2PKPubkeys([p.toHex(true)]);
      p = p.add(secp256k1.Point.BASE);
    }
    // Post-clear the gate still validates and still rejects.
    expect(dedupeP2PKPubkeys([p.toHex(true)])).toHaveLength(1);
    expect(() => dedupeP2PKPubkeys([_xonly('s')])).toThrow(/prepend '02'/);
  });

  test('normalizeHashlock rejects 65 hex chars (regex anchored both ends)', () => {
    expect(() => normalizeHashlock('a'.repeat(65))).toThrow(/64-character hex/);
  });

  test('normalizeHashlock rejects non-string input outright', () => {
    // A single-element array coerces to a 64-hex string, so only the typeof
    // check stands between it and .toLowerCase() blowing up.
    expect(() => normalizeHashlock(['e'.repeat(64)] as any)).toThrow(/64-character hex/);
  });
});

describe('normalizeP2PKOptions canonical output shape', () => {
  const pk = _comp('a');
  const refundPk = _comp('b');

  test('minimal P2PK options omit every optional key', () => {
    expect(normalizeP2PKOptions({ kind: 'P2PK', data: pk })).toStrictEqual({
      kind: 'P2PK',
      data: pk,
    });
  });

  test('keeps an explicit sigFlag', () => {
    expect(normalizeP2PKOptions({ kind: 'P2PK', data: pk, sigFlag: 'SIG_ALL' })).toStrictEqual({
      kind: 'P2PK',
      data: pk,
      sigFlag: 'SIG_ALL',
    });
  });

  test('drops a redundant requiredSignatures of 1', () => {
    expect(normalizeP2PKOptions({ kind: 'P2PK', data: pk, requiredSignatures: 1 })).toStrictEqual({
      kind: 'P2PK',
      data: pk,
    });
  });

  test('drops a redundant requiredRefundSignatures of 1', () => {
    expect(
      normalizeP2PKOptions({
        kind: 'P2PK',
        data: pk,
        locktime: 9999,
        refundKeys: [refundPk],
        requiredRefundSignatures: 1,
      }),
    ).toStrictEqual({ kind: 'P2PK', data: pk, locktime: 9999, refundKeys: [refundPk] });
  });

  test('accepts a multi-key P2PK secret within the slot limit', () => {
    // NUT-28 permits up to 11 locking slots ([data, ...pubkeys, ...refund]); a 10-slot
    // secret is comfortably valid. The exact upper bound is enforced in src separately.
    const labels = ['q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p'];
    const [data, ...pubkeys] = labels.map((c) => _comp(c)); // data + 9 pubkeys = 10 slots
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data, pubkeys })).not.toThrow();
  });
});

describe('parseWitnessData preimage handling', () => {
  test('drops an empty-string preimage', () => {
    expect(parseWitnessData({ preimage: '', signatures: [] })).toStrictEqual({ signatures: [] });
  });

  test('keeps a non-empty preimage', () => {
    expect(parseWitnessData({ preimage: 'ab', signatures: [] })).toStrictEqual({
      preimage: 'ab',
      signatures: [],
    });
  });
});

describe('locktime boundaries', () => {
  const mkProof = (tags: string[][]): Proof => ({
    amount: Amount.from(1),
    id: '00000000000',
    C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
    secret: JSON.stringify(['P2PK', { nonce: bytesToHex(randomBytes(32)), data: PUBKEY, tags }]),
  });

  test('a lock expiring exactly now is EXPIRED, not ACTIVE', () => {
    const now = 1_750_000_000;
    vi.useFakeTimers();
    vi.setSystemTime(now * 1000);
    try {
      const result = verifyP2PKSpendingConditions(mkProof([['locktime', String(now)]]));
      expect(result.lockState).toBe('EXPIRED');
      expect(result.path).toBe('UNLOCKED');
    } finally {
      vi.useRealTimers();
    }
  });

  test('a future locktime reports ACTIVE and fails unsigned', () => {
    const future = String(Math.floor(Date.now() / 1000) + 3600);
    const result = verifyP2PKSpendingConditions(mkProof([['locktime', future]]));
    expect(result.lockState).toBe('ACTIVE');
    expect(result.path).toBe('FAILED');
    expect(result.success).toBe(false);
  });

  test('locktime 0 is treated as no locktime (PERMANENT)', () => {
    const result = verifyP2PKSpendingConditions(mkProof([['locktime', '0']]));
    expect(result.lockState).toBe('PERMANENT');
    expect(result.locktime).toBe(Infinity);
  });

  test('a small positive past locktime is EXPIRED, not PERMANENT', () => {
    // 1 second after the epoch is a real, finite locktime firmly in the past.
    const result = verifyP2PKSpendingConditions(mkProof([['locktime', '1']]));
    expect(result.lockState).toBe('EXPIRED');
    expect(result.locktime).toBe(1);
  });

  test('an active locktime still exposes the main keys as expected witnesses', () => {
    const future = String(Math.floor(Date.now() / 1000) + 3600);
    const secretStr = `["P2PK",{"nonce":"aa","data":"${PUBKEY}","tags":[["locktime","${future}"]]}]`;
    expect(getP2PKExpectedWitnessPubkeys(secretStr)).toStrictEqual([PUBKEY]);
  });
});

describe('refund path thresholds', () => {
  const PRIVKEY2 = schnorr.utils.randomSecretKey();
  const PUBKEY2 = bytesToHex(getPubKeyFromPrivKey(PRIVKEY2));
  const PRIVKEY3 = schnorr.utils.randomSecretKey();
  const PUBKEY3 = bytesToHex(getPubKeyFromPrivKey(PRIVKEY3));

  const mkProof = (tags: string[][]): Proof => ({
    amount: Amount.from(1),
    id: '00000000000',
    C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
    secret: JSON.stringify(['P2PK', { nonce: bytesToHex(randomBytes(32)), data: PUBKEY, tags }]),
  });

  test('no refund keys yields an empty, zero-threshold refund path', () => {
    const result = verifyP2PKSpendingConditions(mkProof([]));
    expect(result.refund).toStrictEqual({ pubkeys: [], requiredSigners: 0, receivedSigners: [] });
  });

  test('refund threshold is 0 while the lock is still active', () => {
    const future = String(Math.floor(Date.now() / 1000) + 3600);
    const result = verifyP2PKSpendingConditions(
      mkProof([
        ['locktime', future],
        ['refund', PUBKEY2],
      ]),
    );
    expect(result.lockState).toBe('ACTIVE');
    expect(result.refund.requiredSigners).toBe(0);
  });

  test('expired 2-of-2 refund multisig rejects a single refund signature', () => {
    const tags: string[][] = [
      ['locktime', '21'],
      ['refund', PUBKEY2, PUBKEY3],
      ['n_sigs_refund', '2'],
    ];
    const [oneSig] = signP2PKProofs([mkProof(tags)], [bytesToHex(PRIVKEY2)]);
    const partial = verifyP2PKSpendingConditions(oneSig);
    expect(partial.refund.requiredSigners).toBe(2);
    expect(partial.refund.receivedSigners).toStrictEqual([PUBKEY2]);
    expect(partial.success).toBe(false);
    expect(partial.path).toBe('FAILED');

    const [twoSigs] = signP2PKProofs([mkProof(tags)], [bytesToHex(PRIVKEY2), bytesToHex(PRIVKEY3)]);
    const full = verifyP2PKSpendingConditions(twoSigs);
    expect(full.success).toBe(true);
    expect(full.path).toBe('REFUND');
  });
});

describe('signing edge cases', () => {
  const mkProof = (secret: string, witness?: Proof['witness']): Proof => ({
    amount: Amount.from(1),
    id: '00000000000',
    C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
    secret,
    witness,
  });
  const secretStr = `["P2PK",{"nonce":"aa","data":"${PUBKEY}"}]`;

  test('signP2PKProof accepts a Uint8Array private key', () => {
    const signed = signP2PKProof(mkProof(secretStr), PRIVKEY);
    expect(isP2PKSpendAuthorised(signed)).toBe(true);
  });

  test('signP2PKProofs derives P2BK keys from a Uint8Array private key', () => {
    const privBytes = createRandomSecretKey();
    const pubHex = bytesToHex(getPubKeyFromPrivKey(privBytes));
    const {
      blinded: [P0_],
      Ehex,
    } = deriveP2BKBlindedPubkeys([pubHex]);
    const proof = { ...mkProof(createP2PKsecret(P0_, [])), p2pk_e: Ehex } as any;
    const [signed] = signP2PKProofs([proof], privBytes);
    expect(isP2PKSpendAuthorised(signed)).toBe(true);
  });

  test('signing does not add a preimage key when the witness has none', () => {
    const signed = signP2PKProof(mkProof(secretStr, { signatures: [] }), bytesToHex(PRIVKEY));
    expect(Object.keys(signed.witness as P2PKWitness)).toStrictEqual(['signatures']);
  });

  test('warns per proof when a key is not required, leaving the proof unsigned', () => {
    const otherPriv = schnorr.utils.randomSecretKey();
    const otherPubX = bytesToHex(schnorr.getPublicKey(otherPriv));
    const warn = vi.fn();
    const logger: Logger = {
      error: vi.fn(),
      warn,
      info: vi.fn(),
      debug: vi.fn(),
      trace: vi.fn(),
      log: vi.fn(),
    };
    const [result] = signP2PKProofs([mkProof(secretStr)], bytesToHex(otherPriv), logger);
    expect(warn).toHaveBeenCalledWith(`Proof #1: Signature not required from [02|03]${otherPubX}`);
    expect(result.witness).toBeUndefined();
  });

  test('maybeDeriveP2BKPrivateKeys falls back to legacy slot 0 indexing for HTLC proofs', () => {
    // Pre-fix senders blinded HTLC lock keys from slot 0; those proofs must stay spendable.
    const privBytes = createRandomSecretKey();
    const pubHex = bytesToHex(getPubKeyFromPrivKey(privBytes));
    const {
      blinded: [P0_],
      Ehex,
    } = deriveP2BKBlindedPubkeys([pubHex]); // legacy: first lock key at slot 0
    const secret = `["HTLC",{"nonce":"aa","data":"ec4916dd28fc4c10d78e287ca5d9cc51ee1ae73cbfde08c6b37324cbfaac8bc5","tags":[["pubkeys","${P0_}"]]}]`;
    const proof = { ...mkProof(secret), p2pk_e: Ehex };
    const derived = maybeDeriveP2BKPrivateKeys(bytesToHex(privBytes), proof);
    const derivedPubs = derived.map((k) => bytesToHex(getPubKeyFromPrivKey(hexToBytes(k))));
    expect(derivedPubs).toContain(P0_);
  });

  test('maybeDeriveP2BKPrivateKeys tolerates a missing proof', () => {
    const priv = bytesToHex(createRandomSecretKey());
    expect(maybeDeriveP2BKPrivateKeys(priv, undefined as unknown as Proof)).toStrictEqual([priv]);
  });
});

describe('SIG_ALL edge cases', () => {
  test('hasP2PKSignedProof throws for a SIG_ALL proof when no message is supplied', () => {
    // A witness (even with empty signatures) is needed to clear the no-witness guard and
    // reach the SIG_ALL branch, which cannot verify without the message to sign.
    const proof: Proof = {
      amount: Amount.from(1),
      id: '00000000000',
      C: '03'.padEnd(66, '0'),
      secret: createP2PKsecret(PUBKEY, [['sigflag', 'SIG_ALL']]),
      witness: { signatures: [] },
    };
    expect(() => hasP2PKSignedProof(PUBKEY, proof)).toThrow(/Cannot verify a SIG_ALL proof/);
  });

  test('hasP2PKSignedProof returns false for a witness-less SIG_ALL proof (no early throw)', () => {
    // The no-witness guard must short-circuit before the SIG_ALL/message check: a SIG_ALL
    // proof with no witness reports "not signed" rather than throwing for a missing message.
    const proof: Proof = {
      amount: Amount.from(1),
      id: '00000000000',
      C: '03'.padEnd(66, '0'),
      secret: createP2PKsecret(PUBKEY, [['sigflag', 'SIG_ALL']]),
    };
    expect(hasP2PKSignedProof(PUBKEY, proof)).toBe(false);
  });

  test('assertSigAllInputs names the proof whose kind differs from the first', () => {
    const data = 'ec4916dd28fc4c10d78e287ca5d9cc51ee1ae73cbfde08c6b37324cbfaac8bc5';
    const tags = [['sigflag', 'SIG_ALL']];
    const s1 = createSecret('HTLC', data, tags);
    const s2 = createSecret('P2PK', data, tags);
    expect(() => assertSigAllInputs([{ secret: s1 } as any, { secret: s2 } as any])).toThrow(
      'Proof #2 is not HTLC',
    );
  });

  test('assertSigAllInputs names the proof that is not SIG_ALL', () => {
    const s1 = createP2PKsecret(PUBKEY, [['sigflag', 'SIG_ALL']]);
    const s2 = createP2PKsecret(PUBKEY, [['sigflag', 'SIG_INPUTS']]);
    expect(() => assertSigAllInputs([{ secret: s1 } as any, { secret: s2 } as any])).toThrow(
      'Proof #2 is not SIG_ALL',
    );
  });

  test('isP2PKSigAll is true when any input is SIG_ALL, false when none is', () => {
    const sigAll = { secret: createP2PKsecret(PUBKEY, [['sigflag', 'SIG_ALL']]) } as any;
    const sigInputs = { secret: createP2PKsecret(PUBKEY) } as any;
    expect(isP2PKSigAll([sigInputs, sigAll])).toBe(true);
    expect(isP2PKSigAll([sigInputs])).toBe(false);
    expect(isP2PKSigAll([])).toBe(false);
  });
});

