    const result = utils.getDecodedToken(token, ['009a1f293253e41e']);
    expect(result).toStrictEqual(expected);
    // and the P2BK fields must survive re-encoding byte-for-byte
    expect(utils.getEncodedToken(result)).toBe(token);
  });
});

