describe('response body size cap', () => {
  const endpoint = mintUrl + '/v1/keys';

  // A hand-rolled streamed Response: a plain reader so tests control chunk delivery and can
  // simulate a body that stalls mid-stream (never delivering `done`). Avoids the ReadableStream
  // global, which lint flags as unsupported on the declared Node floor.
  const streamResponse = (
    chunks: Uint8Array[],
    opts: { hangAfter?: boolean; status?: number; contentLength?: number } = {},
  ): Response => {
    const { hangAfter = false, status = 200, contentLength } = opts;
    const headers = new Headers({ 'Content-Type': 'application/json' });
    if (contentLength !== undefined) headers.set('Content-Length', String(contentLength));
    let i = 0;
    let stalled: ((r: { done: boolean; value?: Uint8Array }) => void) | undefined;
    const cancel = () => {
      stalled?.({ done: true, value: undefined });
      return Promise.resolve();
    };
    const reader = {
      read: () =>
        new Promise<{ done: boolean; value?: Uint8Array }>((resolve) => {
          if (i < chunks.length) return resolve({ done: false, value: chunks[i++] });
          if (!hangAfter) return resolve({ done: true, value: undefined });
          stalled = resolve; // stalled mid-stream; cancel() unblocks it, as a real stream does
        }),
      cancel,
    };
    return {
      ok: status >= 200 && status < 300,
      status,
      headers,
      body: { getReader: () => reader, cancel },
      text: async () => new TextDecoder().decode(concatChunks(chunks)),
    } as unknown as Response;
  };

  const concatChunks = (chunks: Uint8Array[]): Uint8Array => {
    const total = chunks.reduce((n, c) => n + c.byteLength, 0);
    const out = new Uint8Array(total);
    let off = 0;
    for (const c of chunks) {
      out.set(c, off);
      off += c.byteLength;
    }
    return out;
  };
  const enc = (s: string) => new TextEncoder().encode(s);

  afterEach(() => vi.restoreAllMocks());

  test('rejects a success body over the cap via Content-Length pre-check', async () => {
    const response = streamResponse([], { contentLength: 64 * 1024 * 1024 });
    const cancel = vi.spyOn(response.body!, 'cancel');
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(response);
    const thrown = await request({ endpoint, maxResponseBytes: 1000 }).catch((e) => e);
    expect(thrown).toBeInstanceOf(HttpResponseError);
    expect((thrown as Error).message).toMatch(/exceeds 1000 bytes/);
    expect(cancel).toHaveBeenCalledOnce();
  });

  test('rejects a streamed success body that exceeds the cap without Content-Length', async () => {
    const chunk = enc('y'.repeat(600));
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(streamResponse([chunk, chunk]));
    const thrown = await request({ endpoint, maxResponseBytes: 1000 }).catch((e) => e);
    expect(thrown).toBeInstanceOf(HttpResponseError);
    expect((thrown as Error).message).toMatch(/exceeds 1000 bytes/);
  });

  test('accepts a streamed body within the cap', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      streamResponse([enc(JSON.stringify({ keysets: [] }))]),
    );
    const result = await request({ endpoint, maxResponseBytes: 1000 });
    expect(result).toEqual({ keysets: [] });
  });

  test('accepts a within-cap body split across many chunks', async () => {
    const chunks = new Array<Uint8Array>(150_000).fill(enc('x'));
    const text = await readBodyText(streamResponse(chunks), chunks.length);
    expect(text).toHaveLength(chunks.length);
  });

  test('rejects an oversized error body but still surfaces an HttpResponseError', async () => {
    const chunk = enc('z'.repeat(600));
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      streamResponse([chunk, chunk], { status: 500 }),
    );
    const thrown = await request({ endpoint, maxResponseBytes: 1000, idempotent: false }).catch(
      (e) => e,
    );
    // The body read fails, but the status still drives a normal HttpResponseError.
    expect(thrown).toBeInstanceOf(HttpResponseError);
    expect((thrown as Error).message).toBe('bad response');
    expect((thrown as InstanceType<typeof HttpResponseError>).status).toBe(500);
  });

  test('rejects a non-positive maxResponseBytes', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(streamResponse([]));
    await expect(request({ endpoint, maxResponseBytes: 0 })).rejects.toThrow(
      'maxResponseBytes must be a positive integer',
    );
  });

  test('timeout during a hung body read maps to NetworkError', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation(async () =>
      streamResponse([enc('{"keysets":')], { hangAfter: true }),
    );
    const thrown = await request({ endpoint, requestTimeout: 100, idempotent: false }).catch(
      (e) => e,
    );
    expect(thrown).toBeInstanceOf(NetworkError);
    expect((thrown as Error).message).toContain('Request timed out after 100ms');
  });

  test('caller abort during a hung body read maps to CallerAbortError', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation(async () =>
      streamResponse([enc('{"keysets":')], { hangAfter: true }),
    );
    const ac = new AbortController();
    setTimeout(() => ac.abort(), 25);
    const thrown = await request({ endpoint, signal: ac.signal }).catch((e) => e);
    expect(thrown).toBeInstanceOf(NetworkError);
    expect((thrown as Error).name).toBe('CallerAbortError');
  });

  // No `body` stream (eg React Native / custom transports): forces the response.text() fallback.
  const noStreamResponse = (opts: {
    text: () => Promise<string>;
    status?: number;
    contentLength?: number;
  }): Response => {
    const { status = 200, contentLength } = opts;
    const headers = new Headers();
    if (contentLength !== undefined) headers.set('Content-Length', String(contentLength));
    return {
      ok: status >= 200 && status < 300,
      status,
      headers,
      body: null,
      text: opts.text,
    } as unknown as Response;
  };

  test('returns a within-cap body on the no-stream fallback', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      noStreamResponse({ text: async () => JSON.stringify({ keysets: [] }) }),
    );
    const result = await request({ endpoint, maxResponseBytes: 1000 });
    expect(result).toEqual({ keysets: [] });
  });

  test('returns a no-stream fallback body under a requestTimeout that does not fire', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      noStreamResponse({ text: async () => JSON.stringify({ ok: true }) }),
    );
    const result = await request({ endpoint, maxResponseBytes: 1000, requestTimeout: 1000 });
    expect(result).toEqual({ ok: true });
  });

  test('rejects an over-cap body on the no-stream fallback (no Content-Length)', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      noStreamResponse({ text: async () => 'y'.repeat(1008) }),
    );
    const thrown = await request({ endpoint, maxResponseBytes: 10 }).catch((e) => e);
    expect(thrown).toBeInstanceOf(HttpResponseError);
    expect((thrown as Error).message).toMatch(/exceeds 10 bytes/);
  });

  test('a foreign stream-read error surfaces as the stable "bad response"', async () => {
    const reader = {
      read: () => Promise.reject(new Error('stream broke')),
      cancel: () => Promise.resolve(),
    };
    vi.spyOn(globalThis, 'fetch').mockResolvedValue({
      ok: true,
      status: 200,
      headers: new Headers(),
      body: { getReader: () => reader },
      text: async () => '',
    } as unknown as Response);
    const thrown = await request({ endpoint }).catch((e) => e);
    expect(thrown).toBeInstanceOf(HttpResponseError);
    expect((thrown as Error).message).toBe('bad response');
  });

  test('timeout stops a hung no-stream fallback body', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation(async () =>
      noStreamResponse({ text: () => new Promise<string>(() => undefined) }),
    );
    const thrown = await request({ endpoint, requestTimeout: 100, idempotent: false }).catch(
      (e) => e,
    );
    expect(thrown).toBeInstanceOf(NetworkError);
    expect((thrown as Error).message).toContain('Request timed out after 100ms');
  }, 2000);

  test('does not start a no-stream body read after the caller aborts', async () => {
    let textCalls = 0;
    const ac = new AbortController();
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      noStreamResponse({
        text: async () => {
          textCalls++;
          return '{}';
        },
      }),
    );
    const thrown = await request({
      endpoint,
      signal: ac.signal,
      onResponseMeta: () => ac.abort(),
    }).catch((e) => e);
    expect(thrown).toBeInstanceOf(NetworkError);
    expect((thrown as Error).name).toBe('CallerAbortError');
    expect(textCalls).toBe(0);
  });

  test('a timed-out uncancellable no-stream read is not retried on a non-cached endpoint', async () => {
    let fetchCount = 0;
    vi.spyOn(globalThis, 'fetch').mockImplementation(async () => {
      fetchCount++;
      return noStreamResponse({ text: () => new Promise<string>(() => undefined) });
    });
    const thrown = await request({ endpoint, requestTimeout: 5 }).catch((e) => e);
    expect(thrown).toBeInstanceOf(NetworkError);
    expect(fetchCount).toBe(1);
  }, 2000);

  test('timeout during a hung error body maps to NetworkError, not a 5xx', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation(async () =>
      noStreamResponse({ status: 500, text: () => new Promise<string>(() => undefined) }),
    );
    const thrown = await request({ endpoint, requestTimeout: 100, idempotent: false }).catch(
      (e) => e,
    );
    expect(thrown).toBeInstanceOf(NetworkError);
    expect((thrown as Error).message).toContain('Request timed out after 100ms');
  }, 2000);

  test('caller abort during a hung error body maps to CallerAbortError, not a 4xx', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation(async () =>
      noStreamResponse({ status: 404, text: () => new Promise<string>(() => undefined) }),
    );
    const ac = new AbortController();
    setTimeout(() => ac.abort(), 25);
    const thrown = await request({ endpoint, signal: ac.signal }).catch((e) => e);
    expect(thrown).toBeInstanceOf(NetworkError);
    expect((thrown as Error).name).toBe('CallerAbortError');
  }, 2000);

  test('a timed-out uncancellable no-stream read is not retried on a cached endpoint', async () => {
    // The read cannot be cancelled and may still be consuming the body; retrying would start a
    // second one. A cancellable read would retry up to 10x here, so assert exactly one fetch.
    let fetchCount = 0;
    vi.spyOn(globalThis, 'fetch').mockImplementation(async () => {
      fetchCount++;
      return noStreamResponse({ text: () => new Promise<string>(() => undefined) });
    });
    const thrown = await request({
      endpoint,
      requestTimeout: 5,
      ttl: 60000,
      cached_endpoints: [{ method: 'GET', path: '/v1/keys' }],
    }).catch((e) => e);
    expect(thrown).toBeInstanceOf(NetworkError);
    expect(fetchCount).toBe(1);
  }, 2000);
});

describe('parseRetryAfter', () => {
  test('returns undefined for null', () => {
    expect(parseRetryAfter(null)).toBeUndefined();
  });

  test('returns undefined for empty string', () => {
    expect(parseRetryAfter('')).toBeUndefined();
  });

  test('parses delta-seconds to milliseconds', () => {
    expect(parseRetryAfter('30')).toBe(30_000);
  });

  test('parses zero delta-seconds', () => {
    expect(parseRetryAfter('0')).toBe(0);
  });

  test('returns undefined for non-integer delta-seconds', () => {
    expect(parseRetryAfter('3.5')).toBeUndefined();
  });

  test('returns undefined for negative delta-seconds string', () => {
    // Negative values like "-1" don't match /^\d+$/ and contain no letters so bypass HTTP-date parsing too, returning undefined directly
    expect(parseRetryAfter('-1')).toBeUndefined();
  });

  test('parses HTTP-date in the future', () => {
    const futureDate = new Date(Date.now() + 60_000).toUTCString();
    const result = parseRetryAfter(futureDate);
    expect(result).toBeGreaterThan(55_000);
    expect(result).toBeLessThanOrEqual(60_000);
  });

  test('clamps HTTP-date in the past to 0', () => {
    const pastDate = new Date(Date.now() - 10_000).toUTCString();
    expect(parseRetryAfter(pastDate)).toBe(0);
  });

  test('returns undefined for garbage string', () => {
    expect(parseRetryAfter('not-a-date-or-number')).toBeUndefined();
  });
});

describe('detectBrowserLike', () => {
  test('true: browser main thread (window + document)', () => {
    expect(detectBrowserLike({ window: { document: {} } })).toBe(true);
  });

  test('true: classic worker (self instanceof WorkerGlobalScope)', () => {
    class WorkerGlobalScope {}
    const self = new WorkerGlobalScope();
    expect(detectBrowserLike({ self, WorkerGlobalScope })).toBe(true);
  });

  test('true: module worker (no importScripts, but WorkerGlobalScope present)', () => {
    // Module workers omit importScripts; the WorkerGlobalScope check still catches them.
    class WorkerGlobalScope {}
    const self = new WorkerGlobalScope();
    expect(detectBrowserLike({ self, WorkerGlobalScope })).toBe(true);
  });

  test('true: service worker (subclass of WorkerGlobalScope)', () => {
    class WorkerGlobalScope {}
    class ServiceWorkerGlobalScope extends WorkerGlobalScope {}
    const self = new ServiceWorkerGlobalScope();
    expect(detectBrowserLike({ self, WorkerGlobalScope })).toBe(true);
  });

  test('false: Node-like (no window, no WorkerGlobalScope)', () => {
    expect(detectBrowserLike({})).toBe(false);
  });

  test('false: self present but WorkerGlobalScope undefined (RN/Bun shape)', () => {
    expect(detectBrowserLike({ self: {} })).toBe(false);
  });

  test('false: window present but document undefined (partial polyfill)', () => {
    expect(detectBrowserLike({ window: {} })).toBe(false);
  });

  test('false: WorkerGlobalScope present but self is not an instance of it', () => {
    class WorkerGlobalScope {}
    expect(detectBrowserLike({ self: {}, WorkerGlobalScope })).toBe(false);
  });
});

describe('buildRequestHeaders', () => {
  test('non-browser runtimes get the Mozilla/5.0 User-Agent override', () => {
    expect(buildRequestHeaders(undefined, undefined, false)['User-Agent']).toBe('Mozilla/5.0');
  });

  test('browser-like runtimes omit the User-Agent override', () => {
    expect(buildRequestHeaders(undefined, undefined, true)['User-Agent']).toBeUndefined();
  });

  test('caller-supplied User-Agent always wins', () => {
    expect(buildRequestHeaders(undefined, { 'User-Agent': 'X' }, false)['User-Agent']).toBe('X');
    expect(buildRequestHeaders(undefined, { 'User-Agent': 'X' }, true)['User-Agent']).toBe('X');
  });

  test('Content-Type is added only when body is present', () => {
    expect(buildRequestHeaders('{"x":1}', undefined, false)['Content-Type']).toBe(
      'application/json',
    );
    expect(buildRequestHeaders(undefined, undefined, false)['Content-Type']).toBeUndefined();
  });

  test('Accept is always present', () => {
    expect(buildRequestHeaders(undefined, undefined, true).Accept).toBe(
      'application/json, text/plain, */*',
    );
  });
});

describe('errorMessage', () => {
  test('returns err.message when err is an Error', () => {
    expect(errorMessage(new Error('boom'), 'fallback')).toBe('boom');
  });

  test('returns fallback when err is not an Error (string, null, undefined, plain object)', () => {
    expect(errorMessage('not an error', 'fallback')).toBe('fallback');
    expect(errorMessage(null, 'fallback')).toBe('fallback');
    expect(errorMessage(undefined, 'fallback')).toBe('fallback');
    expect(errorMessage({ message: 'looks like an error' }, 'fallback')).toBe('fallback');
  });
});

describe('RateLimitError', () => {
  test('is an instance of HttpResponseError', () => {
    const err = new RateLimitError('rate limited');
    expect(err).toBeInstanceOf(HttpResponseError);
    expect(err).toBeInstanceOf(RateLimitError);
    expect(err).toBeInstanceOf(Error);
  });

  test('has status 429', () => {
    const err = new RateLimitError('rate limited');
    expect(err.status).toBe(429);
  });

  test('has name RateLimitError', () => {
    const err = new RateLimitError('rate limited');
    expect(err.name).toBe('RateLimitError');
  });

  test('stores retryAfterMs when provided', () => {
    const err = new RateLimitError('rate limited', 5000);
    expect(err.retryAfterMs).toBe(5000);
  });

  test('retryAfterMs is undefined when omitted', () => {
    const err = new RateLimitError('rate limited');
    expect(err.retryAfterMs).toBeUndefined();
  });

  test('thrown on 429 with Retry-After header parsed', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return new HttpResponse(JSON.stringify({ error: 'Too Many Requests' }), {
          status: 429,
          headers: { 'Retry-After': '60' },
        });
      }),
    );

    try {
      await request({ endpoint });
      expect.unreachable();
    } catch (e) {
      expect(e).toBeInstanceOf(RateLimitError);
      const err = e as InstanceType<typeof RateLimitError>;
      expect(err.message).toBe('429 Too Many Requests');
      expect(err.status).toBe(429);
      expect(err.retryAfterMs).toBe(60_000);
    }
  });

  test('thrown on 429 without Retry-After header', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return new HttpResponse(JSON.stringify({ error: 'Too Many Requests' }), {
          status: 429,
        });
      }),
    );

    try {
      await request({ endpoint });
      expect.unreachable();
    } catch (e) {
      expect(e).toBeInstanceOf(RateLimitError);
      const err = e as InstanceType<typeof RateLimitError>;
      expect(err.retryAfterMs).toBeUndefined();
    }
  });
});

describe('onResponseMeta callback', () => {
  test('fires on 200 response with full meta', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json(
          { keysets: [] },
          {
            headers: {
              RateLimit: 'limit=100, remaining=99, reset=60',
              'RateLimit-Policy': '100;w=60',
            },
          },
        );
      }),
    );

    let captured: ResponseMeta | undefined;
    await request({ endpoint, onResponseMeta: (m) => (captured = m) });

    expect(captured).toBeDefined();
    expect(captured!.endpoint).toBe(endpoint);
    expect(captured!.status).toBe(200);
    expect(captured!.rateLimit).toBe('limit=100, remaining=99, reset=60');
    expect(captured!.rateLimitPolicy).toBe('100;w=60');
    expect(captured!.retryAfterMs).toBeUndefined();
    expect(captured!.headers).toBeInstanceOf(Headers);
  });

  test('fires on 429 BEFORE RateLimitError is thrown', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return new HttpResponse(JSON.stringify({ error: 'Too Many Requests' }), {
          status: 429,
          headers: { 'Retry-After': '30' },
        });
      }),
    );

    let captured: ResponseMeta | undefined;
    try {
      await request({ endpoint, onResponseMeta: (m) => (captured = m) });
      expect.unreachable();
    } catch (e) {
      expect(e).toBeInstanceOf(RateLimitError);
    }
    expect(captured).toBeDefined();
    expect(captured!.endpoint).toBe(endpoint);
    expect(captured!.status).toBe(429);
    expect(captured!.retryAfterMs).toBe(30_000);
  });

  test('fires on other 4xx BEFORE HttpResponseError is thrown', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return new HttpResponse(JSON.stringify({ error: 'Not Found' }), { status: 404 });
      }),
    );

    let captured: ResponseMeta | undefined;
    try {
      await request({ endpoint, onResponseMeta: (m) => (captured = m) });
      expect.unreachable();
    } catch (e) {
      expect(e).toBeInstanceOf(HttpResponseError);
    }
    expect(captured).toBeDefined();
    expect(captured!.endpoint).toBe(endpoint);
    expect(captured!.status).toBe(404);
  });

  test('fires on 5xx BEFORE HttpResponseError is thrown', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return new HttpResponse(JSON.stringify({ error: 'Internal Server Error' }), {
          status: 500,
        });
      }),
    );

    let captured: ResponseMeta | undefined;
    try {
      await request({ endpoint, onResponseMeta: (m) => (captured = m) });
      expect.unreachable();
    } catch (e) {
      expect(e).toBeInstanceOf(HttpResponseError);
    }
    expect(captured).toBeDefined();
    expect(captured!.endpoint).toBe(endpoint);
    expect(captured!.status).toBe(500);
  });

  test('reads Cloudflare lowercase Ratelimit header variant', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json(
          { keysets: [] },
          {
            headers: {
              Ratelimit: 'limit=50, remaining=49, reset=30',
              'Ratelimit-Policy': '50;w=30',
            },
          },
        );
      }),
    );

    let captured: ResponseMeta | undefined;
    await request({ endpoint, onResponseMeta: (m) => (captured = m) });

    expect(captured).toBeDefined();
    expect(captured!.endpoint).toBe(endpoint);
    expect(captured!.rateLimit).toBe('limit=50, remaining=49, reset=30');
    expect(captured!.rateLimitPolicy).toBe('50;w=30');
  });

  test('no callback means no error and identical behaviour', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json({ keysets: [] });
      }),
    );

    // No onResponseMeta — should not throw
    const result = await request({ endpoint });
    expect(result).toEqual({ keysets: [] });
  });

  test('rateLimit and rateLimitPolicy are undefined when headers absent', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json({ keysets: [] });
      }),
    );

    let captured: ResponseMeta | undefined;
    await request({ endpoint, onResponseMeta: (m) => (captured = m) });

    expect(captured).toBeDefined();
    expect(captured!.endpoint).toBe(endpoint);
    expect(captured!.rateLimit).toBeUndefined();
    expect(captured!.rateLimitPolicy).toBeUndefined();
  });

  test('throwing callback is swallowed via safeCallback', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json({ keysets: [] });
      }),
    );

    const warnSpy = vi.fn();
    setRequestLogger({ ...NULL_LOGGER, warn: warnSpy });

    const result = await request({
      endpoint,
      onResponseMeta: () => {
        throw new Error('boom');
      },
    });

    setRequestLogger(NULL_LOGGER);

    expect(result).toEqual({ keysets: [] });
    expect(warnSpy).toHaveBeenCalledOnce();
    expect(warnSpy).toHaveBeenCalledWith(
      'callback failed',
      expect.objectContaining({
        op: 'request.onResponseMeta',
        endpoint,
        error: expect.any(Error),
      }),
    );
  });

  test('async rejection in callback does not produce unhandled rejection', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json({ keysets: [] });
      }),
    );

    const warnSpy = vi.fn();
    setRequestLogger({ ...NULL_LOGGER, warn: warnSpy });

    const result = await request({
      endpoint,
      // eslint-disable-next-line @typescript-eslint/no-misused-promises -- async-callback tolerance is what's under test
      onResponseMeta: async () => {
        throw new Error('async boom');
      },
    });

    // Give microtask queue time to flush so the .catch handler fires
    await new Promise((r) => setTimeout(r, 10));

    setRequestLogger(NULL_LOGGER);

    expect(result).toEqual({ keysets: [] });
    expect(warnSpy).toHaveBeenCalledOnce();
    expect(warnSpy).toHaveBeenCalledWith(
      'callback failed',
      expect.objectContaining({
        op: 'request.onResponseMeta',
        endpoint,
        error: expect.any(Error),
      }),
    );
  });

  test('composes per-request and global callbacks', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json({ keysets: [] });
      }),
    );

    const perRequestSpy = vi.fn();
    const globalSpy = vi.fn();

    setGlobalRequestOptions({ onResponseMeta: globalSpy });

    await request({ endpoint, onResponseMeta: perRequestSpy });

    setGlobalRequestOptions({});

    expect(perRequestSpy).toHaveBeenCalledOnce();
    expect(globalSpy).toHaveBeenCalledOnce();
    expect(perRequestSpy.mock.calls[0][0].endpoint).toBe(endpoint);
    expect(globalSpy.mock.calls[0][0].endpoint).toBe(endpoint);
  });

  test('global callback fires even when per-request callback throws sync', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json({ keysets: [] });
      }),
    );

    const globalSpy = vi.fn();
    const warnSpy = vi.fn();
    setRequestLogger({ ...NULL_LOGGER, warn: warnSpy });
    setGlobalRequestOptions({ onResponseMeta: globalSpy });

    const result = await request({
      endpoint,
      onResponseMeta: () => {
        throw new Error('per-request boom');
      },
    });

    setGlobalRequestOptions({});
    setRequestLogger(NULL_LOGGER);

    expect(result).toEqual({ keysets: [] });
    expect(globalSpy).toHaveBeenCalledOnce();
    expect(warnSpy).toHaveBeenCalledOnce();
    expect(warnSpy).toHaveBeenCalledWith(
      'callback failed',
      expect.objectContaining({ scope: 'per-request' }),
    );
  });

  test('global callback fires even when per-request callback rejects async', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return HttpResponse.json({ keysets: [] });
      }),
    );

    const globalSpy = vi.fn();
    const warnSpy = vi.fn();
    setRequestLogger({ ...NULL_LOGGER, warn: warnSpy });
    setGlobalRequestOptions({ onResponseMeta: globalSpy });

    const result = await request({
      endpoint,
      // eslint-disable-next-line @typescript-eslint/no-misused-promises -- async-callback tolerance is what's under test
      onResponseMeta: async () => {
        throw new Error('per-request async boom');
      },
    });

    // flush microtask queue for async .catch handler
    await new Promise((r) => setTimeout(r, 10));

    setGlobalRequestOptions({});
    setRequestLogger(NULL_LOGGER);

    expect(result).toEqual({ keysets: [] });
    expect(globalSpy).toHaveBeenCalledOnce();
    expect(warnSpy).toHaveBeenCalledOnce();
    expect(warnSpy).toHaveBeenCalledWith(
      'callback failed',
      expect.objectContaining({ scope: 'per-request' }),
    );
  });
});

