          unit: 'sat',
          pubkey: LOCK_PUBKEY,
          state: MintQuoteState.UNPAID,
          expiry: null,
          amount_paid: 0,
          amount_issued: 0,
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
