    const quote = await wallet.createMintQuoteBolt12(LOCK_PUBKEY);
    expect(quote.quote).toBe('q-bolt12');
    expect(body.pubkey).toBe(LOCK_PUBKEY);
    expect(body.amount).toBeUndefined();
    expect(body.description).toBeUndefined();
