  test('rejects when the mint returns a quote locked to a different pubkey', async () => {
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt12', () =>
        HttpResponse.json({
          quote: 'q-bolt12-other',
          request: 'lno1offer...',
