describe('prepareMint mutants', () => {
  test('rejects a string quote id', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    await expect(
      wallet.prepareMint('bolt11', 1, 'just-an-id' as unknown as { quote: string }),
