  });

  test('does not add fee outputs when minting (includeFees is false)', async () => {
    useFeeKeyset(1000);
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    const quote: MintQuoteBolt11Response = {
      quote: 'q-fee',
      request: 'lnbc...',
      amount: Amount.from(8),
