      payment_preimage: null,
      unit: 'sat',
      method: 'bolt11',
    };
    // sum 11, feeReserve 1 → the non-custom path would create a single blank.
    const proofsToSend: Proof[] = [
      { id: KEYSET_ID, amount: Amount.from(11), secret: 's1', C: 'C1' },
    ];
    const meltTxn = await wallet.prepareMelt(
      'bolt11',
      meltQuote,
      proofsToSend,
