import { hexToBytes } from '@noble/curves/utils.js';
import { HttpResponse, http } from 'msw';
import { test, describe, expect } from 'vitest';

import {
  Wallet,
  Amount,
  CTSError,
  OutputData,
  createEphemeralCounterSource,
  type Proof,
  type ProofLike,
  type OutputConfig,
} from '../../src';
import { Bytes } from '../../src/utils';

import { useTestServer, mint, mintUrl, unit, logger, mintInfoResp } from './_setup';

const server = useTestServer();
const mintInfoRespWithNut12 = {
  ...mintInfoResp,
  nuts: { ...mintInfoResp.nuts, 12: { supported: true } },
};

function expectNUT10SecretDataToEqual(p: Proof[], s: string) {
  p.forEach((p) => {
    const parsedSecret = JSON.parse(p.secret);
    expect(parsedSecret[1].data).toBe(s);
  });
}

const plainSecret = '1f98e6837a434644c9411825d7c6d6e13974b931f8f0652217cea29010674a13';
const unknownKindSecret = JSON.stringify([
  'TEST',
  { nonce: 'test1', data: 'some-test-data', tags: [] },
]);
const p2pkSecret = JSON.stringify([
  'P2PK',
  {
    nonce: 'abc123',
    data: '02' + 'aa'.repeat(32),
    tags: [],
  },
]);

describe('sendOffline witness normalization', () => {
  test('strips witness from plain (non-NUT-10) secret', async () => {
    const wallet = new Wallet(mint, { unit, requireSigDleq: true });
    await wallet.loadMint();

    const proofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: plainSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        witness: JSON.stringify({ signatures: ['deadbeef'] }),
      },
    ];

    const { send } = wallet.sendOffline(1, proofs);
    expect(send).toHaveLength(1);
    expect(send[0].witness).toBeUndefined();
  });

  test('preserves witness on NUT-10 P2PK secret', async () => {
    const wallet = new Wallet(mint, { unit, requireSigDleq: true });
    await wallet.loadMint();

    const witnessStr = JSON.stringify({ signatures: ['cafebabe'] });
    const proofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: p2pkSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        witness: witnessStr,
      },
    ];

    const { send } = wallet.sendOffline(1, proofs);
    expect(send).toHaveLength(1);
    expect(send[0].witness).toBe(witnessStr);
  });

  test('serializes object witness on NUT-10 secret to JSON string', async () => {
    const wallet = new Wallet(mint, { unit, requireSigDleq: true });
    await wallet.loadMint();

    const witnessObj = { signatures: ['cafebabe'] };
    const proofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: p2pkSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        witness: witnessObj,
      },
    ];

    const { send } = wallet.sendOffline(1, proofs);
    expect(send).toHaveLength(1);
    expect(send[0].witness).toBe(JSON.stringify(witnessObj));
  });

  test('no-change when proof has no witness', async () => {
    const wallet = new Wallet(mint, { unit, requireSigDleq: true });
    await wallet.loadMint();

    const proofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: plainSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      },
    ];

    const { send } = wallet.sendOffline(1, proofs);
    expect(send).toHaveLength(1);
    expect(send[0].witness).toBeUndefined();
  });

  test('throws when no offline selection matches, rather than returning an empty send', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    // Enough funds (6 >= 3) but no exact subset of {2, 4} sums to 3.
    const proofs: Proof[] = [
      { id: '00bd033559de27d0', amount: Amount.from(2), secret: 's1', C: 'C1' },
      { id: '00bd033559de27d0', amount: Amount.from(4), secret: 's2', C: 'C2' },
    ];

    expect(() => wallet.sendOffline(3, proofs)).toThrow(/cannot be completed offline/);
  });

  test('refuses to select proofs from another unit on the same mint', async () => {
    const usdKeysetId = '009a1f293253e41f';
    server.use(
      http.get(mintUrl + '/v1/keysets', () =>
        HttpResponse.json({
          keysets: [
            { id: '00bd033559de27d0', unit: 'sat', active: true, input_fee_ppk: 0 },
            { id: usdKeysetId, unit: 'usd', active: true, input_fee_ppk: 0 },
          ],
        }),
      ),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const usdProof: Proof = {
      id: usdKeysetId,
      amount: Amount.from(1),
      secret: 's-usd',
      C: 'C-usd',
    };
    const satProof: Proof = {
      id: '00bd033559de27d0',
      amount: Amount.from(1),
      secret: 's-sat',
      C: 'C-sat',
    };

    // Alone, and mixed into an otherwise valid sat pool.
    expect(() => wallet.sendOffline(1, [usdProof])).toThrow(/unrecognised keyset/);
    expect(() => wallet.sendOffline(2, [satProof, usdProof])).toThrow(/unrecognised keyset/);
  });

  test('preserves witness on NUT-10 unknown secret kind', async () => {
    const wallet = new Wallet(mint, { unit, requireSigDleq: true });
    await wallet.loadMint();

    const witnessStr = JSON.stringify({ signatures: ['cafebabe'] });
    const proofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: unknownKindSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        witness: witnessStr,
      },
    ];

    const { send } = wallet.sendOffline(1, proofs);
    expect(send).toHaveLength(1);
    expect(send[0].witness).toBe(witnessStr);
  });

  test('mixed proofs: strips from plain, keeps on P2PK', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const witnessStr = JSON.stringify({ signatures: ['cafebabe'] });
    const proofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: plainSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        witness: JSON.stringify({ signatures: ['deadbeef'] }),
      },
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: p2pkSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        witness: witnessStr,
      },
    ];

    const { send } = wallet.sendOffline(2, proofs);
    expect(send).toHaveLength(2);
    // plain secret — witness stripped
    const plain = send.find((p) => p.secret === plainSecret)!;
    expect(plain.witness).toBeUndefined();
    // P2PK secret — witness kept
    const p2pk = send.find((p) => p.secret === p2pkSecret)!;
    expect(p2pk.witness).toBe(witnessStr);
  });

  test('accepts deserialized ProofLike[] input', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const storedProofs = JSON.parse(
      JSON.stringify([
        {
          id: '00bd033559de27d0',
          amount: Amount.from(1),
          secret: plainSecret,
          C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        },
      ]),
    ) as ProofLike[];

    const { send } = wallet.sendOffline(1, storedProofs);
    expect(send).toHaveLength(1);
    expect(send[0].amount).toEqual(Amount.from(1));
  });

  test('preserves p2pk_e on offline send proofs', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const proofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: p2pkSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        p2pk_e: '02' + 'bb'.repeat(32),
      },
    ];

    const { send } = wallet.sendOffline(1, proofs);
    expect(send).toHaveLength(1);
    expect(send[0].p2pk_e).toBe(proofs[0].p2pk_e);
  });
});

describe('sendOffline requireDleq', () => {
  // v3 (BLS) proofs satisfy requireDleq via pairing equivalence — they carry no DLEQ proof
  // but the receive-side `hasValidDleq` accepts them. sendOffline must mirror that.
  const v3Id = '02ce4c47836fd0e64f37a08254777b7fd0dedb95fc1ddd0acadf5600674c743c5d';
  const v3Secret = 'test_message';
  const v3C =
    'b7a4881059133fd91a8753600d9a5e524c65d6224f6fe2d5aef9e59f1507fdad90b3b4d48ee46da5c8dfaa0b88e28b69';
  // BLS12-381 G2 base point compressed (192 hex / 96 bytes) — only loaded for keyset
  // resolution / fee lookup in this test; not used cryptographically.
  const G2_BASE_HEX =
    '93e02b6052719f607dacd3a088274f65596bd0d09920b61ab5da61bbdc7f5049334cf11213945d57e5ac7d055d042b7e024aa2b2f08f0a91260805272dc51051c6e47ad4fa403b02b4510b647ae3d1770bac0326a805bbefd48056c8c121bdb8';
  const v3Keyset = { id: v3Id, unit, active: true, input_fee_ppk: 0, final_expiry: null };
  const v3Keys = { ...v3Keyset, keys: { '1': G2_BASE_HEX, '2': G2_BASE_HEX } };

  function mockV3Keyset() {
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [v3Keyset] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [v3Keys] })),
      http.get(mintUrl + '/v1/keys/' + v3Id, () => HttpResponse.json({ keysets: [v3Keys] })),
    );
  }

  test('accepts v3 proofs even when requireDleq is true (pairing replaces DLEQ)', async () => {
    mockV3Keyset();
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const v3Proofs: Proof[] = [{ id: v3Id, amount: Amount.from(1), secret: v3Secret, C: v3C }];

    const { send } = wallet.sendOffline(1, v3Proofs, { requireDleq: true });
    expect(send).toHaveLength(1);
    expect(send[0].id).toBe(v3Id);
    expect(send[0].dleq).toBeUndefined();
  });

  test('rejects v1/v2 proofs without DLEQ when requireDleq is true', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    const v1Proofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: plainSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      },
    ];
    expect(() => wallet.sendOffline(1, v1Proofs, { requireDleq: true })).toThrow(
      'Not enough funds available to send',
    );
  });
});

describe('send', () => {
  const proofs = [
    {
      id: '00bd033559de27d0',
      amount: Amount.from(1),
      secret: '1f98e6837a434644c9411825d7c6d6e13974b931f8f0652217cea29010674a01',
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
    },
  ];
  test('test send base case', async () => {
    server.use(
      http.post(mintUrl + '/v1/swap', () => {
        return HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422',
            },
          ],
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const result = await wallet.send(1, proofs);

    expect(result.keep).toHaveLength(0);
    expect(result.send).toHaveLength(1);
    expect(result.send[0]).toMatchObject({ amount: Amount.from(1), id: '00bd033559de27d0' });
    expect(/[0-9a-f]{64}/.test(result.send[0].C)).toBe(true);
    expect(/[0-9a-f]{64}/.test(result.send[0].secret)).toBe(true);
  });

  test('rejects missing DLEQ on swap when mint advertises NUT-12', async () => {
    const swapProofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(2),
        secret: '1f98e6837a434644c9411825d7c6d6e13974b931f8f0652217cea29010674a02',
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      },
    ];
    server.use(
      http.get(mintUrl + '/v1/info', () => HttpResponse.json(mintInfoRespWithNut12)),
      http.post(mintUrl + '/v1/swap', () =>
        HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422',
            },
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d423',
            },
          ],
        }),
      ),
    );
    const wallet = new Wallet(mint, { unit, requireSigDleq: true });
    await wallet.loadMint();

    await expect(wallet.send(1, swapProofs)).rejects.toThrow(
      'Mint supports NUT-12, but returned a signature without DLEQ proof',
    );
  });

  test('test send accepts AmountLike values', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const amountInputs = [Amount.from(1), 1n, '1'] as const;
    for (const amount of amountInputs) {
      const result = await wallet.send(amount, proofs);
      expect(result.keep).toHaveLength(0);
      expect(result.send).toHaveLength(1);
      expect(result.send[0]).toMatchObject({ amount: Amount.from(1), id: '00bd033559de27d0' });
    }
  });

  test('test send accepts deserialized ProofLike[] input', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const storedProofs = JSON.parse(JSON.stringify(proofs)) as ProofLike[];
    const result = await wallet.send(1, storedProofs);

    expect(result.keep).toHaveLength(0);
    expect(result.send).toHaveLength(1);
    expect(result.send[0]).toMatchObject({ amount: Amount.from(1), id: '00bd033559de27d0' });
  });

  test('preserves p2pk_e when exact-match send avoids swap', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const exactMatchProofs: Proof[] = [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(1),
        secret: p2pkSecret,
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        p2pk_e: '02' + 'cc'.repeat(32),
      },
    ];

    const result = await wallet.send(1, exactMatchProofs);

    expect(result.keep).toHaveLength(0);
    expect(result.send).toHaveLength(1);
    expect(result.send[0].p2pk_e).toBe(exactMatchProofs[0].p2pk_e);
  });

  test('test send over paying. Should return change', async () => {
    server.use(
      http.post(mintUrl + '/v1/swap', () => {
        return HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422',
            },
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422',
            },
          ],
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const result = await wallet.send(1, [
      {
        id: '00bd033559de27d0',
        amount: Amount.from(2),
        secret: '1f98e6837a434644c9411825d7c6d6e13974b931f8f0652217cea29010674a03',
        C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      },
    ]);

    expect(result.send).toHaveLength(1);
    expect(result.send[0]).toMatchObject({ amount: Amount.from(1), id: '00bd033559de27d0' });
    expect(/[0-9a-f]{64}/.test(result.send[0].C)).toBe(true);
    expect(/[0-9a-f]{64}/.test(result.send[0].secret)).toBe(true);
    expect(result.keep).toHaveLength(1);
    expect(result.keep[0]).toMatchObject({ amount: Amount.from(1), id: '00bd033559de27d0' });
    expect(/[0-9a-f]{64}/.test(result.keep[0].C)).toBe(true);
    expect(/[0-9a-f]{64}/.test(result.keep[0].secret)).toBe(true);
  });
  test('test send overpaying with p2pk.', async () => {
    server.use(
      http.post(mintUrl + '/v1/swap', () => {
        return HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422',
            },
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422',
            },
          ],
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const result = await wallet.send(
      1,
      [
        {
          id: '00bd033559de27d0',
          amount: Amount.from(2),
          secret: '1f98e6837a434644c9411825d7c6d6e13974b931f8f0652217cea29010674a04',
          C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
        },
      ],
      {
        // p2pk: { pubkey: 'pk' }
      },
      {
        send: { type: 'p2pk', options: { kind: 'P2PK', data: '02' + 'aa'.repeat(32) } },
      },
    );

    expectNUT10SecretDataToEqual([result.send[0]], '02' + 'aa'.repeat(32));
    expect(result.keep[0].secret.length).toBe(64);
  });

  test('test send over paying2', async () => {
    server.use(
      http.post(mintUrl + '/v1/swap', () => {
        return HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422',
            },
            {
