  test('supportsAmountless() correctly detects amountless option in melt methods', async () => {
    const info = new MintInfo({
      name: 'Test Mint',
      pubkey: '0296d0aa13b6a31cf0cd974249f28c7b7176d7274712c95a41c7d8066d3f29d679',
